typedef long long ll;

int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *x = (ll *)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) scanf("%lld", &x[i]);

    qsort(x, N, sizeof(ll), cmp_ll);

    /*
      Key facts:
      - Every allowed move flips an odd number (prime >= 3) of consecutive cards.
      - So each move changes the parity of the number of face-up cards.
      - Also, any interval of odd length >= 3 can be used, in particular length 3.
      - Using only length-3 moves, we can eliminate any interior card pattern greedily from left to right:
        if card i is up, flip [i, i+1, i+2].
      - This process leaves only the last two positions relevant, and for a finite set of up cards,
        the minimum number of operations depends only on parity:
          * if N is even: impossible with N-1 moves, achievable in N moves
          * if N is odd : achievable in N-1 moves
      - Therefore answer is:
          N-1 if N is odd
          N   if N is even
      - Special case N=0 does not appear in input constraints here; if it did, answer would be 0.
    */

    if (N % 2 == 1) {
        printf("%d\n", N - 1);
    } else {
        printf("%d\n", N);
    }

    free(x);
    return 0;
}

