vector<int> primes;
const int MAXV = 10000000;

void sieve() {
    vector<bool> is_prime(MAXV+1, true);
    is_prime[0] = is_prime[1] = false;
    for (int i = 2; i <= MAXV; i++) {
        if (is_prime[i]) {
            if (i >= 3) primes.push_back(i);
            for (int j = i*2; j <= MAXV; j += i)
                is_prime[j] = false;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    sieve();

    int N;
    cin >> N;
    vector<int> x(N);
    for (int i = 0; i < N; i++) cin >> x[i];

    if (N == 0) {
        cout << 0 << "\n";
        return 0;
    }

    unordered_set<int> up(x.begin(), x.end());
    vector<int> pos(up.begin(), up.end());
    sort(pos.begin(), pos.end());
    int m = pos.size();

    // Check if any two can be paired with prime distance >=3
    unordered_set<int> primeSet(primes.begin(), primes.end());
    vector<bool> used(m, false);
    int ops = 0;

    for (int i = 0; i < m; i++) {
        if (used[i]) continue;
        bool paired = false;
        for (int j = i+1; j < m; j++) {
            if (used[j]) continue;
            int d = pos[j] - pos[i];
            if (d >= 3 && primeSet.count(d)) {
                used[i] = used[j] = true;
                ops++;
                paired = true;
                break;
            }
        }
        if (!paired) {
            // single leftover
            // need to handle: can be done in 2 ops if we use two flips
            // But if count of unpaired is even, we can pair them in 2 ops each pair
        }
    }

    // Remaining unpaired
    vector<int> rem;
    for (int i = 0; i < m; i++) if (!used[i]) rem.push_back(pos[i]);

    int r = rem.size();
    if (r == 0) {
        cout << ops << "\n";
        return 0;
    }

    // For remaining, we can clear each in 2 operations (Goldbach: any even >=4 is sum of two primes >=3)
    // But if r is odd, one needs 3 operations (since odd+2=odd can be covered by 3)
    if (r % 2 == 0) {
        ops += r; // each pair in 2 ops: r/2 pairs * 2 = r
    } else {
        ops += (r-1) + 3; // (r-1) even -> (r-1) ops for those, plus 3 for last
    }

    cout << ops << "\n";
    return 0;
}

