import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        long[] x = new long[N];
        for (int i = 0; i < N; i++) x[i] = fs.nextLong();

        if (N == 0) {
            System.out.println(0);
            return;
        }

        // Key fact:
        // Flipping any odd-length consecutive segment (prime >= 3 is odd) changes
        // the parity of the number of face-up cards.
        //
        // Also, using length 3 only, any finite configuration can be cleared.
        // Thus the minimum number depends only on parity:
        // - if N is even -> possible in N operations, and impossible in fewer due to parity
        // - if N is odd  -> possible in 1 operation iff all up cards form one prime-length
        //                   consecutive block; otherwise possible in N-1 operations
        //
        // More precisely, the answer is:
        //   even N: N
        //   odd N:
        //     if the set is exactly [a, a+1, ..., a+L-1] and L is prime >= 3 -> 1
        //     else -> N-1
        //
        // Reason:
        // - Every operation toggles an odd number of cards, so parity of #up flips each time.
        //   To go from N to 0, number of operations must have same parity as N.
        // - Any two up cards can be removed with one 3-flip plus one new temporary card,
        //   and these temporary effects can be chained, giving constructions with N or N-1 ops.
        // - One operation is possible exactly when current up cards are one prime-length
        //   consecutive segment.

        if ((N & 1) == 0) {
            System.out.println(N);
            return;
        }

        // N is odd.
        if (isConsecutiveBlock(x)) {
            long len = x[N - 1] - x[0] + 1;
            if (len == N && len >= 3 && isPrime(len)) {
                System.out.println(1);
                return;
            }
        }

        System.out.println(N - 1);
    }

    static boolean isConsecutiveBlock(long[] x) {
        for (int i = 1; i < x.length; i++) {
            if (x[i] != x[i - 1] + 1) return false;
        }
        return true;
    }

    static boolean isPrime(long n) {
        if (n < 2) return false;
        if (n % 2 == 0) return n == 2;
        for (long d = 3; d * d <= n; d += 2) {
            if (n % d == 0) return false;
        }
        return true;
    }

    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
